  automaticEnabled: true, lockId: 17369921, lockKey: 'human_tracker_sync_lock', tableIdNative: '17369920', intakeSince: '2026-11-09T00:00:00Z', readEndRow: 1000,
  pilots: [
    ['72:1121466','recjxE3w0eaeFgYBW','Ozarke'],
