function readGrid(sheetResponse,config=CONFIG){
  assert(sheetResponse.spreadsheetId===config.spreadsheetId,'Wrong destination spreadsheet');
  const output={};
  for(const [kind,id,width,keyColumn] of [['tracker',config.trackerSheetId,12,10],['source',config.sourceSheetId,18,0]]){
    const sheet=sheetResponse.sheets?.find(s=>s.properties?.sheetId===id);
    assert(sheet,`Missing ${kind} sheet`);
    assert(sheet.properties.gridProperties.columnCount===26,'Destination columns changed; full-width read must be reviewed');
    assert(sheet.properties.gridProperties.rowCount>=1000,'Destination grid is smaller than the read contract');
    const cells=new Map();
    for(const block of sheet.data||[]){
      const startRow=block.startRow||0,startColumn=block.startColumn||0;
      (block.rowData||[]).forEach((row,i)=>{
        const target=cells.get(startRow+i)||Array.from({length:26},()=>({}));
        (row.values||[]).forEach((cell,j)=>{if(startColumn+j<26)target[startColumn+j]=cell;});
        cells.set(startRow+i,target);
      });
    }
    const header=(cells.get(config.firstDataRow-1)||[]).slice(0,width).map(cellValue).map(normalized);
    assert(JSON.stringify(header)===JSON.stringify(HEADERS[kind].map(normalized)),`${kind} headers changed`);
    const rows=new Map();
    for(const [rowIndex,rowCells] of cells){
      if(rowIndex<config.firstDataRow)continue;
      const values=rowCells.map(cellValue);if(values.every(v=>v==='')&&rowCells.every(c=>!c.userEnteredValue))continue;
      const key=String(values[keyColumn]);
      assert(/^72:\d+$/.test(key),`${kind} has a populated row without a valid Human key`);
      assert(!rows.has(key),`${kind} has duplicate opportunity IDs`);
      rows.set(key,{rowIndex,cells:rowCells,values});
    }
    output[kind]={sheet,rows,cells};
  }
  assert(output.tracker.rows.size===output.source.rows.size,'Source and Tracker row counts differ');
  for(const key of output.tracker.rows.keys())assert(output.source.rows.has(key),'Tracker key missing from source');
  const table=output.tracker.sheet.tables?.find(t=>String(t.tableId)===String(config.tableIdNative));
  assert(table,'Missing native Tracker table metadata');
  const range=table.range;
  assert(range?.sheetId===config.trackerSheetId&&range.startRowIndex===config.firstDataRow-1&&
    (range.startColumnIndex||0)===0&&range.endColumnIndex===12&&Number.isInteger(range.endRowIndex)&&range.endRowIndex<=config.readEndRow,'Native table range changed');
  for(const [index,value]of [[3,'Unknown'],[4,'Unknown'],[7,'Needs review']]){
    const col=table.columnProperties?.find(c=>(c.columnIndex||0)===index);
    assert(col?.columnType==='DROPDOWN'&&col.dataValidationRule?.condition?.type==='ONE_OF_LIST'&&col.dataValidationRule.condition.values.some(v=>v.userEnteredValue===value),'Native table validation changed');
  }
  for(const row of output.tracker.rows.values())assert(row.rowIndex<range.endRowIndex,'Native table does not cover existing tracker row');
  const recordIds=new Set();
  for(const [key,row]of output.source.rows){
    assert(/^rec[A-Za-z0-9]{14}$/.test(row.values[17]),'Invalid source record anchor');
    assert(!recordIds.has(row.values[17]),'Duplicate source record anchors');recordIds.add(row.values[17]);
    assert(row.cells[0]?.userEnteredValue?.stringValue===key&&row.cells[17]?.userEnteredValue?.stringValue===row.values[17],'Source anchors must be literal');
    assert(output.tracker.rows.get(key).cells[10]?.userEnteredValue?.stringValue===key,'Tracker anchor must be literal');
  }
  output.table=table;
  return output;
}

function fingerprint(sheetResponse,config=CONFIG){
