function valueCell(value){
  if(value==='')return {};
  if(typeof value==='number'){assert(Number.isFinite(value),'Non-finite cell number');return {userEnteredValue:{numberValue:value}};}
  if(typeof value==='boolean')return {userEnteredValue:{boolValue:value}};
