function businessDomain(email){
 const s=String(email).trim().toLowerCase();
 if(!/^[^\s@]+@(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$/.test(s)||isTeamEmail(s))return '';
