function intakeReason(record,now,config=CONFIG){
 try{
  if(!/^rec[A-Za-z0-9]{14}$/.test(record.id))return 'invalid_source_identity';
  const created=serialDate(record.createdTime,true),cutoff=serialDate(config.intakeSince,true),current=serialDate(now,true);
  if(created===''||created<cutoff)return 'historical_before_intake';
  if(created>current)return 'future_source_record';
  const modified=serialDate(field(record,'last_updated_time'),true);
  if(modified===''||modified<created||modified>current)return 'stale_or_invalid_modified_time';
  const company=String(field(record,'Company Name')).trim();
  if(company.length<2||company.length>160||!/[\p{L}]/u.test(company)||/^[=+@-]|[\x00-\x1f]/.test(company)||/^(unknown|n\/?a|none|test|company)$/i.test(company))return 'unclear_company';
  if(!businessDomain(field(record,'Leads Email')))return 'non_business_or_team_email';
  if(!['New Interested','In Conversation','Booked Meeting'].includes(String(field(record,'Pipeline Stage'))))return 'pipeline_requires_review';
  if(field(record,'DNC')!==''&&field(record,'DNC')!==false)return 'do_not_contact';
  safeInboxUrl(field(record,'Master Inbox Link'));
  serialDate(field(record,'First Inbound Reply At'),true);serialDate(field(record,'First Response At'),true);serialDate(field(record,'Date of Call Booked'));
  return '';
 }catch{return 'invalid_source_evidence';}
}
function rowIsEmpty(cells){return !cells||cells.every(c=>!c.userEnteredValue&&!c.effectiveValue&&!c.note&&!c.formattedValue);}
function newRowPlan(record,key,rowIndex,config){
 const campaign=String(field(record,'campaign_id')),stage=String(field(record,'Pipeline Stage'));
 const offer=campaign==='619'?'AI search / free page':['620','621'].includes(campaign)?'Four finished Meta ads':String(field(record,'Campaign Name'));
