function newRowRequests(entry,config){
 assert(/^72:[1-9]\d*$/.test(entry.key)&&/^rec[A-Za-z0-9]{14}$/.test(entry.recordId),'Invalid new-row identity');
 assert(entry.sourceValues?.length===18&&entry.sourceValues[0]===entry.key&&entry.sourceValues[17]===entry.recordId,'New source anchors differ');
 assert(['Unknown','Not applicable'].includes(entry.ads),'Invalid initial manual value');
 assert(Number.isInteger(entry.rowIndex)&&entry.rowIndex>=config.firstDataRow&&entry.rowIndex<config.readEndRow,'Invalid new row range');
 const requests=[],values=newRowPlanValues(entry);
 for(const [kind,sheetId,width]of [['source',config.sourceSheetId,18],['tracker',config.trackerSheetId,12]]){
  requests.push({copyPaste:{source:{sheetId,startRowIndex:config.firstDataRow,endRowIndex:config.firstDataRow+1,startColumnIndex:0,endColumnIndex:width},destination:{sheetId,startRowIndex:entry.rowIndex,endRowIndex:entry.rowIndex+1,startColumnIndex:0,endColumnIndex:width},pasteType:'PASTE_FORMAT',pasteOrientation:'NORMAL'}});
  values[kind].forEach((cell,column)=>requests.push({updateCells:{range:{sheetId,startRowIndex:entry.rowIndex,endRowIndex:entry.rowIndex+1,startColumnIndex:column,endColumnIndex:column+1},rows:[{values:[cell]}],fields:'userEnteredValue'}}));
