function lockRequest(runToken,config=CONFIG){
 assert(/^human-tracker:[A-Za-z0-9_-]+$/.test(runToken||''),'Missing unique workflow execution token');
 return {requests:[{createDeveloperMetadata:{developerMetadata:{metadataId:config.lockId,metadataKey:config.lockKey,metadataValue:runToken,visibility:'DOCUMENT',location:{spreadsheet:true}}}}],includeSpreadsheetInResponse:false};
}
function requireOwnLock(sheetResponse,runToken,config=CONFIG){
 lockRequest(runToken,config);
 const locks=(sheetResponse.developerMetadata||[]).filter(m=>m.metadataId===config.lockId||m.metadataKey===config.lockKey);
 assert(locks.length===1,'Tracker mutex missing or duplicated; stop and review lock recovery');
 const m=locks[0];
 assert(m.metadataId===config.lockId&&m.metadataKey===config.lockKey&&m.metadataValue===runToken&&m.visibility==='DOCUMENT'&&m.location?.spreadsheet===true,'Tracker mutex belongs to another execution; do not write or release');
 return true;
}
function releaseLockRequest(runToken,config=CONFIG){
