function assert(condition,message){if(!condition)throw new Error(message);}
function plain(value){
  if(value===null||value===undefined)return '';
  if(typeof value==='object'&&typeof value.name==='string')return value.name;
  assert(['string','number','boolean'].includes(typeof value),'Unsupported source value shape');
  return value;
}
function field(record,name){
  const values=record.cellValuesByFieldId || record.fields || record;
  return plain(values[FIELDS[name]] ?? values[name]);
}
function cellValue(cell){
  const v=cell?.effectiveValue || cell?.userEnteredValue;
  if(!v)return '';
  assert(!v.errorValue,'Destination contains a formula error');
  return v.stringValue ?? v.numberValue ?? v.boolValue ?? '';
}
function normalized(s){return String(s).trim().replace(/\s+/g,' ').toLowerCase();}
function serialDate(value,datetime=false){
  if(value===''||value===null||value===undefined)return '';
  const s=String(value);
  assert(datetime?/T.*(?:Z|[+-]\d\d:\d\d)$/.test(s):/^\d{4}-\d{2}-\d{2}$/.test(s), 'Source date has wrong shape or lacks timezone');
  const n=Date.parse(s);assert(Number.isFinite(n),'Invalid source date');
  if(!datetime)assert(new Date(n).toISOString().slice(0,10)===s,'Invalid calendar date');
  return n/86400000+25569;
}
function safeInboxUrl(value){
  const s=String(value);
  assert(/^https:\/\/send\.dulcy\.io\/inbox\?reply_uuid=[a-f0-9-]{36}$/i.test(s),'Unexpected conversation link destination or ID');
  return s;
}
function isTeamEmail(email){
